{
  "findings": [
    {
      "check_id": "CKV_GCP_113",
      "title": "Ensure IAM policy should not define public access",
      "resource": "google_iam_workload_identity_pool_provider.pass2",
      "severity": "MEDIUM",
      "explanation": "The attribute_condition in this resource is overly permissive and could allow unintended access. It should be scoped more narrowly to ensure only the intended entities can authenticate."
    }
  ],
  "patched_code": "resource \"google_iam_workload_identity_pool_provider\" \"pass2\" {\n  workload_identity_pool_id          = \"example-pool\"\n  workload_identity_pool_provider_id = \"example-provider-2\"\n  attribute_mapping                 = {\n    \"google.subject\"       = \"assertion.sub\"\n  }\n  attribute_condition               = \"assertion.sub == 'repo:myOrg/myRepo:ref:refs/heads/main' && assertion.repository_owner == 'myOrg'\"\n  oidc {\n    issuer_uri                       = \"https://token.actions.githubusercontent.com\"\n  }\n}\n",
  "fix_summary": "Scoped the attribute_condition to include an additional check for the repository owner, reducing the risk of unintended access."
}
